const raw = ($json.response || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
return {
  json: {
    ...$json,
    summary: raw
  }
};

const articles = $input.all().map(item => item.json);

const summary = articles
  .map((article, index) => {
    const sourceList = Array.isArray(article.sourceNames) && article.sourceNames.length
      ? article.sourceNames.join(', ')
      : (article.source || 'Unknown source');
    return `${index + 1}. **${article.title}** (${sourceList})\n${article.summary}`;
  })
  .join('\n\n');

return [{
  json: {
    articles,
    summary
  }
}];

