parameters.jsCode:
const overviewResponse = ($json.response || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
const articles = Array.isArray($json.articles) ? $json.articles : [];

const now = new Date();
const pad = n => String(n).padStart(2, '0');
const date = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;

const unique = values => [...new Set((values || []).filter(Boolean))];

const articlesSection = articles.map(article => {
  const sourceEntries = Array.isArray(article.sources) && article.sources.length
    ? article.sources
    : [{
        name: article.source || 'Unknown source',
        link: article.link || article.url || '',
        pubDate: article.pubDate || '',
      }];

  const sourceLine = sourceEntries
    .map(source => source.link ? `[${source.name}](${source.link})` : source.name)
    .join(', ');
  const dateLine = unique(sourceEntries.map(source => source.pubDate || article.pubDate)).join(', ');
  const metaLine = [
    sourceLine ? `**Sources:** ${sourceLine}` : '',
    dateLine ? `**Dates:** ${dateLine}` : '',
    article.place ? `**Place:** ${article.place}` : ''
  ].filter(Boolean).join('  \n');

  return [
    `### ${article.title}`,
    metaLine,
    '',
    article.summary || '',
  ].join('\n');
}).join('\n\n---\n\n');

const text = [
  `# Daily News Briefing — ${date}`,
  '',
  '## Overview',
  overviewResponse,
  '',
  '---',
  '',
  '## Articles',
  '',
  articlesSection
].join('\n');

return [{
  json: {
    text,
    summaryText: text,
    filename: `news-summary-${date}.md`,
    subject: `Daily News Summary - ${date}`,
    overview: overviewResponse,
    articles
  }
}];

const today = new Date().toISOString().split('T')[0];

return [{
  json: {
    articles: $input.all()
      .map(({ json }) => json)
      .filter(post => {
        const rawDate = post.date || post.isoDate || '';
        return rawDate.startsWith(today);
      })
      .map(post => ({
        title: (post.title?.rendered || '').replace(/<[^>]+>/g, '').trim(),
        link: post.link || '',
        snippet: (post.excerpt?.rendered || '').replace(/<[^>]+>/g, '').trim(),
        pubDate: post.date || post.isoDate || '',
        selector: '.entry-content',
        source: 'Tempo News',
        place: 'Carpi'
      })),
    required: ['title', 'link']
  }
}];

const scrapedItems = $input.all().map(item => item.json || {});

/**
 * Ensure the value is always an array.
 */
const toArray = (value) => Array.isArray(value) ? value : (value ? [value] : []);

/**
 * Normalize text:
 * - convert null/undefined to ''
 * - collapse multiple spaces/newlines
 * - trim
 */
const normalizeText = (value) => String(value || '').replace(/\s+/g, ' ').trim();

/**
 * Convert any date-like value to YYYY-MM-DD using JS Date.
 * Returns '' if invalid.
 */
const toDateKey = (value) => {
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return '';

  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');

  return `${y}-${m}-${day}`;
};

/**
 * Convert relative URLs to absolute URL on voce.it.
 * WARNING: URL api can't be used in n8n nodes!
 */
const toAbsoluteUrl = (href) => {
  const raw = String(href || '').trim();
  if (!raw || raw.toLowerCase() === 'null') return '';

  // Already absolute
  if (/^https?:\/\//i.test(raw)) return raw;

  // Normalize common relative formats used by your scraper
  let path = raw;

  // remove leading ../ or ./
  path = path.replace(/^(\.\.\/)+/, '/');
  path = path.replace(/^\.\//, '/');

  // ensure it starts with /
  if (!path.startsWith('/')) path = `/${path}`;

  // keep only target domain
  return `https://www.voce.it${path}`;
};

/**
 * Italian month map (short + full).
 */
const monthMap = {
  gen: 1, gennaio: 1,
  feb: 2, febbraio: 2,
  mar: 3, marzo: 3,
  apr: 4, aprile: 4,
  mag: 5, maggio: 5,
  giu: 6, giugno: 6,
  lug: 7, luglio: 7,
  ago: 8, agosto: 8,
  set: 9, settembre: 9,
  ott: 10, ottobre: 10,
  nov: 11, novembre: 11,
  dic: 12, dicembre: 12
};

/**
 * Normalize a raw date into YYYY-MM-DD.
 * Handles:
 * - numeric forms: 05/05/2026, 05-05-2026, 05.05.2026
 * - Italian text forms: 5 Mag 2026, 5 Maggio 2026
 * - fallback to JS Date parser
 */
const normalizeDate = (rawDate) => {
  const text = normalizeText(rawDate);
  if (!text) return '';

  // 1) Numeric date
  const numeric = text.match(/(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})/);
  if (numeric) {
    const day = Number(numeric[1]);
    const month = Number(numeric[2]);
    const year = Number(numeric[3].length === 2 ? `20${numeric[3]}` : numeric[3]);

    if (day >= 1 && day <= 31 && month >= 1 && month <= 12) {
      return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    }
  }

  // 2) Italian textual date
  const monthText = text
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

  const textDate = monthText.match(/(\d{1,2})\s+([a-z]+)\s+(\d{4})/);
  if (textDate) {
    const day = Number(textDate[1]);
    const month = monthMap[textDate[2]];
    const year = Number(textDate[3]);

    if (month && day >= 1 && day <= 31) {
      return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    }
  }

  // 3) Fallback
  return toDateKey(text);
};

/**
 * Return true if text looks like a supported date.
 */
const isDateLike = (value) => !!normalizeDate(value);

const seen = new Set();
const articles = [];

/**
 * Push one article only if title/link/date are valid.
 * De-duplicates by lowercased link + title.
 */
const pushArticle = (title, rawLink, rawDate) => {
  const normalizedTitle = normalizeText(title);
  const link = toAbsoluteUrl(rawLink);
  const pubDate = normalizeDate(rawDate);

  if (!normalizedTitle || !link || !pubDate) return;

  const dedupeKey = `${link.toLowerCase()}|${normalizedTitle.toLowerCase()}`;
  if (seen.has(dedupeKey)) return;
  seen.add(dedupeKey);

  articles.push({
    title: normalizedTitle,
    link,
    pubDate,
    selector: '[itemprop="articleBody"]',
    source: 'La Voce',
    place: 'Carpi',
  });
};

for (const scraped of scrapedItems) {
  const timelineTexts = toArray(scraped.timelineTexts).map(normalizeText).filter(Boolean);
  const rawTimelineLinks = toArray(scraped.timelineLinks);

  // Keep only usable non-null/non-empty links, normalized.
  const timelineLinks = rawTimelineLinks
    .map(normalizeText)
    .filter(v => v && v.toLowerCase() !== 'null');

  /**
   * TIMELINE MODE (robust):
   * Instead of fixed index pairing (i += 2), scan text sequence.
   * Whenever we hit a date-like text, pair it with the previous non-date text as title.
   * Then assign the next available link.
   */
  if (timelineTexts.length && timelineLinks.length) {
    let linkCursor = 0;
    let lastNonDateText = '';

    for (const text of timelineTexts) {
      if (isDateLike(text)) {
        const title = lastNonDateText;
        const link = timelineLinks[linkCursor] || '';
        const rawDate = text;

        // advance link cursor only when we try to emit a timeline record
        linkCursor++;

        pushArticle(title, link, rawDate);
      } else {
        // Keep latest non-date candidate; when next date appears,
        // this will be considered the related title.
        lastNonDateText = text;
      }
    }

    // Continue to next scraped block (fallback not needed if timeline was processed)
    continue;
  }

  /**
   * FALLBACK MODE:
   * Standard parallel arrays titles/links/dates.
   */
  const titleList = toArray(scraped.titles).map(normalizeText);
  const linkList = toArray(scraped.links).map(normalizeText);
  const dateList = toArray(scraped.dates).map(normalizeText);
  const maxLen = Math.max(titleList.length, linkList.length, dateList.length);

  for (let i = 0; i < maxLen; i++) {
    pushArticle(titleList[i] || '', linkList[i] || '', dateList[i] || '');
  }
}

/**
 * Keep only articles of today.
 * NOTE: n8n runtime timezone can affect "today".
 */
const today = toDateKey(new Date());
const todays = articles.filter(article => article.pubDate === today);

return [{
  json: {
    articles: todays,
    required: ['title', 'link']
  }
}];

const normalizeText = (value) => String(value || '').replace(/\s+/g, ' ').trim();
const normalizeLink = (value) => normalizeText(value).replace(/\/$/, '').toLowerCase();

const stopWords = new Set([
  'the','and','for','with','from','that','this','into','about','after','before','between','under','over','into','without',
  'gli','delle','della','dello','dell','alla','allo','agli','dalle','dalla','dallo','sulla','sullo','nelle','nella','nell',
  'per','con','una','uno','del','dei','degli','dai','dalle','dal','dalla','alla','alle','sul','sui','sulle','nel','nei','nelle',
  'che','chi','non','piu','più','come','dopo','prima','anche','sono','oggi','ieri','news','ultima','ultime'
]);

const tokenize = (...parts) => {
  const tokens = new Set();
  parts
    .map(normalizeText)
    .join(' ')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(token => token.length >= 4 && !stopWords.has(token))
    .forEach(token => tokens.add(token));
  return tokens;
};

const overlapRatio = (left, right) => {
  if (!left.size || !right.size) return 0;
  let matches = 0;
  for (const token of left) {
    if (right.has(token)) matches += 1;
  }
  return matches / Math.min(left.size, right.size);
};

const addUnique = (list, value) => {
  const normalized = normalizeText(value);
  if (!normalized) return list;
  if (!list.some(entry => normalizeText(entry) === normalized)) list.push(normalized);
  return list;
};

const addUniqueObject = (list, candidate, keyBuilder) => {
  const key = keyBuilder(candidate);
  if (!key) return list;
  if (!list.some(entry => keyBuilder(entry) === key)) list.push(candidate);
  return list;
};

const merged = [];

for (const item of $input.all()) {
  const batch = item.json || {};
  const articles = Array.isArray(batch.articles) ? batch.articles : [];

  for (const article of articles) {
    const normalizedTitle = normalizeText(article.title);
    const normalizedSnippet = normalizeText(article.snippet);
    const normalizedLink = normalizeLink(article.link || article.url);
    if (!normalizedTitle || !(normalizedLink || normalizedSnippet)) continue;

    const titleTokens = tokenize(normalizedTitle);
    const contextTokens = tokenize(normalizedTitle, normalizedSnippet);
    const sourceEntry = {
      name: normalizeText(article.source) || 'Unknown source',
      title: normalizedTitle,
      snippet: normalizedSnippet,
      link: normalizeText(article.link || article.url),
      pubDate: normalizeText(article.pubDate),
      place: normalizeText(article.place),
    };

    const match = merged.find(existing => {
      if (normalizedLink && existing._links.has(normalizedLink)) return true;
      if (normalizedTitle && existing._titles.has(normalizedTitle.toLowerCase())) return true;
      const titleScore = overlapRatio(titleTokens, existing._titleTokens);
      const contextScore = overlapRatio(contextTokens, existing._contextTokens);
      return titleScore >= 0.8 || contextScore >= 0.7;
    });

    if (!match) {
      merged.push({
        ...article,
        title: normalizedTitle,
        snippet: normalizedSnippet,
        originalTitle: normalizeText(article.originalTitle) || normalizedTitle,
        originalSnippet: normalizeText(article.originalSnippet) || normalizedSnippet,
        translatedTitle: normalizeText(article.translatedTitle),
        translatedSnippet: normalizeText(article.translatedSnippet),
        sources: [sourceEntry],
        sourceNames: [sourceEntry.name],
        sourceLinks: sourceEntry.link ? [sourceEntry.link] : [],
        sourceTitles: sourceEntry.title ? [sourceEntry.title] : [],
        sourceSnippets: sourceEntry.snippet ? [sourceEntry.snippet] : [],
        sourceCount: 1,
        _links: new Set(normalizedLink ? [normalizedLink] : []),
        _titles: new Set([normalizedTitle.toLowerCase()]),
        _titleTokens: titleTokens,
        _contextTokens: contextTokens,
      });
      continue;
    }

    addUniqueObject(match.sources, sourceEntry, entry => `${normalizeText(entry.name).toLowerCase()}|${normalizeLink(entry.link)}|${normalizeText(entry.title).toLowerCase()}`);
    addUnique(match.sourceNames, sourceEntry.name);
    if (sourceEntry.link) addUnique(match.sourceLinks, sourceEntry.link);
    if (sourceEntry.title) addUnique(match.sourceTitles, sourceEntry.title);
    if (sourceEntry.snippet) addUnique(match.sourceSnippets, sourceEntry.snippet);
    if (normalizedLink) match._links.add(normalizedLink);
    if (normalizedTitle) match._titles.add(normalizedTitle.toLowerCase());
    titleTokens.forEach(token => match._titleTokens.add(token));
    contextTokens.forEach(token => match._contextTokens.add(token));
    match.sourceCount = match.sourceNames.length;

    if (normalizedSnippet.length > normalizeText(match.snippet).length) {
      match.snippet = normalizedSnippet;
      if (!normalizeText(match.originalSnippet)) match.originalSnippet = normalizedSnippet;
    }

    if (normalizedTitle.length > normalizeText(match.title).length) {
      match.title = normalizedTitle;
      if (!normalizeText(match.originalTitle)) match.originalTitle = normalizedTitle;
    }

    if (!normalizeText(match.link || match.url) && sourceEntry.link) {
      match.link = sourceEntry.link;
    }

    if (!normalizeText(match.pubDate) && sourceEntry.pubDate) {
      match.pubDate = sourceEntry.pubDate;
    }

    if (!normalizeText(match.place) && sourceEntry.place) {
      match.place = sourceEntry.place;
    }
  }
}

return merged.map(article => {
  const { _links, _titles, _titleTokens, _contextTokens, ...cleanArticle } = article;
  return {
    json: {
      ...cleanArticle,
      source: article.sourceNames[0] || article.source || 'Unknown source',
      link: cleanArticle.link || cleanArticle.url || article.sourceLinks[0] || '',
      relatedLinks: article.sourceLinks,
      relatedTitles: article.sourceTitles,
      relatedSnippets: article.sourceSnippets,
    }
  };
});

